// Facts about Minecraft blocks (kind, solidity, colour) from data/mc_block_db.json, generated by
// scripts/extract-mc-db.ts. Lets the converter run offline without WASM for colour matching.
import type { RGB } from './gameset';
import raw from '../../data/mc_block_db.json';

export interface McBlockFacts {
  kind: string;
  baseBlock: string | null;
  fullCube: boolean;
  transparent: boolean;
  color: RGB | null;
}

type Row = [string, string | null, number, number, number | null, number | null, number | null];
const rows = (raw as unknown as { blocks: Record<string, Row> }).blocks;

export function mcFacts(id: string): McBlockFacts | undefined {
  const r = rows[id];
  if (!r) return undefined;
  return {
    kind: r[0], baseBlock: r[1], fullCube: r[2] === 1, transparent: r[3] === 1,
    color: r[4] === null ? null : [r[4]!, r[5]!, r[6]!],
  };
}

export const mcBlockCount = Object.keys(rows).length;
